from pathlib import Path
from html import escape as e
import re,json,shutil
R=Path('/Users/josenicolassantiagomoreno/Documents/GitHub/Presentaciones');O=R/'curso-ux-ui-paso-a-paso';old=R/'material-profesor-ux-ui';data=json.loads((old/'lecciones-profesor.json').read_text());D=[]
def add(key,where,prep,steps,task,end,board=''):
 x=next(x for x in data if x['id']==key)
 D.append(dict(id=key,title=x['title'],minutes=x['minutes'],where=where,prep=prep,steps=[dict(action=a,say=b,see=c) for a,b,c in steps],task=task,end=end,board=board))
add('1.1','Página web','Pulsa “1. Página web” y después “Versión inicial”. Lleva la página hasta arriba.',[
('Señala con el cursor “Impulsa tu potencial”. No hagas clic todavía.','Si entraras por primera vez, ¿sabrías qué vende esta empresa? El título llama la atención, pero no explica el servicio.','Título genérico y botón “Más”.'),
('Pulsa “Más”. Observa que baja al formulario. Señala “Dato 1” y “Dato 2”.','Puedo llegar al formulario, pero no sé qué me están pidiendo. La experiencia incluye entender cada paso, no solo llegar a él.','El formulario con nombres poco claros.'),
('En la barra superior pulsa “Versión mejorada”. Señala el título y lee su descripción.','Ahora sabemos que Faro ayuda a organizar la atención de un negocio. UI es lo que usamos en pantalla; UX incluye qué entendemos y cómo completamos la tarea.','La oferta explícita y el botón “Solicitar asesoría”.'),
('Pulsa “Solicitar asesoría” dentro de la web. Señala las etiquetas de nombre y correo.','La apariencia del campo forma parte de la interfaz. Entender qué escribir y por qué facilita la experiencia. Ambas trabajan juntas.','Formulario con etiquetas visibles y explicación.'),
('Alterna “Versión inicial” y “Versión mejorada” una última vez.','El cambio no se justifica solo por verse más bonito. Se justifica porque permite comprender mejor el servicio y la solicitud.','Las dos versiones muestran un antes y un después concreto.')],
'Dile: “Pausa el video. Escribe una cosa que veas en la interfaz y una dificultad que podría tener quien la usa”.','Cierra cuando hayas explicado una diferencia de apariencia y otra de comprensión.')
add('1.2','Página web','Pulsa “1. Página web” > “Versión inicial”.',[
('Pulsa “Entrar” en el menú de la web. Señala los dos campos.','Utilidad significa que esto sirva para una necesidad. Aquí queremos solicitar información. Pero que exista un formulario no significa que sea fácil de usar.','Campos “Dato 1” y “Dato 2”.'),
('Haz clic en “Dato 2” y escribe ana@example.com.','El campo acepta texto, pero su nombre no explica qué espera. Esa duda es un problema de usabilidad.','Un correo escrito en un campo cuyo nombre era ambiguo.'),
('Pulsa “Versión mejorada”. Señala el texto y las etiquetas del formulario.','También debemos poder percibir y usar la página. Una etiqueta clara o un texto legible ayudan a que más personas puedan participar.','Etiquetas persistentes y texto oscuro.'),
('Haz clic en el fondo de la web y pulsa Tab varias veces. Mira el borde del elemento enfocado.','También puedo moverme con teclado. Este borde me dice dónde estoy. No estoy comprobando toda la accesibilidad; estoy revisando una parte.','Un contorno visible cambia entre enlaces y controles.'),
('Pulsa Shift + Tab una vez para volver al control anterior.','La tarea debe poder recorrerse y comprenderse. Útil, usable y accesible son preguntas relacionadas que debemos revisar.','El foco retrocede un elemento.')],
'Dile: “Encuentra una palabra confusa y una barrera de lectura en la versión inicial”.','Cierra después de mostrar una barrera y el modo de recorrer los controles con teclado.')
add('1.3','Escribir un ejemplo y página web','Pulsa “3. Escribir un ejemplo”. En “Ejemplo de la clase” elige “1.3”.',[
('Haz clic después de “Pedido inicial:” y escribe “Quiero una web moderna”.','Este pedido habla de apariencia. Todavía no dice qué necesita hacer el visitante.','La frase escrita en el documento de pantalla.'),
('Completa “La persona necesita:” con “Saber si Faro puede ayudarle y cómo pedir información”.','Primero definimos la necesidad. Diseñaremos alrededor de ella.','Una necesidad concreta, distinta del pedido estético.'),
('Completa “Acción principal:” con “Solicitar una conversación inicial”.','Esta será la acción que destacaremos. La empresa recibe una consulta y la persona sabe qué está pidiendo.','Una sola acción principal.'),
('Completa “Cómo lo comprobaré:” con “La persona explica el servicio y llega a la confirmación”.','Esto se puede observar. Decir “se ve moderno” no demuestra que la solicitud se entienda.','Un criterio observable.'),
('Pulsa “1. Página web” > “Versión mejorada”. Señala “Solicitar asesoría”.','Este botón existe porque antes definimos la tarea. La decisión de diseño responde a un objetivo.','La acción del documento reflejada en la página.')],
'Dile: “Escribe qué necesita tu visitante y una acción principal que deba poder realizar”.','Cierra cuando hayas relacionado el objetivo escrito con el botón real.',
'Pedido inicial:\nLa persona necesita:\nEl negocio necesita: recibir consultas que pueda atender.\nAcción principal:\nCómo lo comprobaré:\n')
add('1.4','Editar diseño y página web','Pulsa “2. Editar diseño” > “Reiniciar taller”.',[
('Señala los bloques Oferta, Beneficios, Cómo funciona, Preguntas frecuentes y Contacto.','Esto es un esquema. Nos sirve para decidir qué contenido aparece y en qué orden. Un wireframe es un boceto de estructura.','Cinco bloques con su título.'),
('Pulsa “Bajar” en Oferta. Después pulsa “Subir” en ese mismo bloque.','Puedo discutir el orden antes de diseñar todos los detalles. Cada movimiento debería tener una razón.','Oferta cambia de posición y vuelve al inicio.'),
('Pulsa “1. Página web” > “Versión mejorada”.','Aquí vemos la página desarrollada visualmente: textos, espacios, colores y controles.','La página completa de Faro.'),
('Pulsa “Solicitar asesoría”; escribe Ana y ana@example.com y pulsa el botón de envío.','Un prototipo permite probar acciones. Este ejemplo simula el envío para enseñar sus estados; no manda datos a ninguna empresa.','Primero “Enviando” y después “Solicitud recibida”.'),
('Pulsa “Nueva demostración”.','Nuestro proceso será entender, organizar, diseñar, probar y mejorar. Hoy ya vimos qué tipo de material nos ayuda en cada etapa.','Formulario vacío listo para repetir.')],
'Dile: “Escribe qué decidirías primero: el orden del contenido, el color o la prueba del envío. Explica tu razón”.','Cierra al distinguir esquema, diseño e interacción.')
add('2.1','Escribir un ejemplo','Pulsa “3. Escribir un ejemplo” y elige “2.1”.',[
('Lee el bloque “Dato del caso”.','Esto nos lo da el ejercicio: Faro ofrece una conversación inicial de treinta minutos.','Un dato de la empresa ficticia.'),
('En “Lo que supongo:” escribe “El visitante entiende la palabra asesoría”.','Esto todavía es una suposición. No voy a presentarlo como algo que comprobé con personas.','El supuesto separado del dato.'),
('En “Pregunta que evitaré:” escribe “¿Te gusta esta página tan clara?”.','Esta pregunta incluye mi opinión y puede orientar la respuesta.','Una pregunta que sugiere una valoración.'),
('En “Pregunta que haré:” escribe “Cuéntame la última vez que buscaste ayuda para atender consultas”.','Ahora pregunto por una experiencia. Puedo escuchar qué pasó sin ofrecerle una respuesta.','Una pregunta abierta sobre un hecho pasado.'),
('Añade “¿Qué información buscaste antes de contactar?” en “Otra pregunta:”.','Las respuestas pueden cambiar qué contenido necesitamos mostrar. Primero escuchamos; después decidimos.','Dos preguntas utilizables en una conversación.')],
'Dile: “Escribe dos preguntas sobre experiencias reales. Evita las que solo se responden sí o no”.','Cierra cuando hayas separado un dato, un supuesto y una pregunta.',
'Dato del caso: conversación inicial de 30 minutos.\nLo que supongo:\nPregunta que evitaré:\nPregunta que haré:\nOtra pregunta:\n')
add('2.2','Escribir un ejemplo y página web','Pulsa “3. Escribir un ejemplo” y elige “2.2”.',[
('En la primera fila escribe “¿Qué ofrece Faro?” después de “Comprender”.','Primero la persona necesita entender si llegó al sitio adecuado.','La primera pregunta del recorrido.'),
('Completa las otras tres filas con “¿Cómo funciona?”, “¿Cómo lo solicito?” y “¿Llegó mi solicitud?”.','El recorrido es una secuencia de preguntas y respuestas, no solo una lista de pantallas.','Cuatro pasos completos.'),
('Pulsa “1. Página web” > “Versión inicial”. Busca la duración de la asesoría.','Aquí no encuentro información para saber cómo funciona. Esa ausencia puede dificultar la decisión.','La versión inicial no explica duración ni alcance.'),
('Pulsa “Versión mejorada”. Busca el título “Así funciona”.','Ahora hay una respuesta para esa pregunta: qué envío, cuándo responden y cuánto dura la conversación.','Proceso y condiciones visibles.'),
('Regresa a “3. Escribir un ejemplo”. Añade “Posible dificultad: no saber qué ocurre después del envío”.','Es una dificultad posible. Para saber cómo afecta a una persona necesitamos observarla usando la página.','Una dificultad descrita, sin inventar una prueba.')],
'Dile: “Anota una pregunta que podría tener tu visitante antes de contactar”.','Cierra cuando cada paso tenga una pregunta y hayas localizado una respuesta en la web.',
'Comprender:\nRevisar condiciones:\nSolicitar:\nConfirmar:\nPosible dificultad:\n')
add('2.3','Editar diseño','Pulsa “2. Editar diseño” > “Reiniciar taller”.',[
('Pulsa “Subir” en Contacto tres veces, hasta dejarlo después de Oferta.','Acabo de cambiar el orden. Pedir datos tan pronto puede resultar prematuro si la persona necesita conocer las condiciones.','Contacto queda antes de Beneficios y Proceso.'),
('Pulsa “Bajar” en Contacto tres veces para devolverlo al final.','Para este caso proponemos explicar primero y pedir después. Es una propuesta que depende de la tarea.','Se recupera la secuencia original.'),
('Haz clic en el título “Cómo funciona”. Selecciona sus palabras y escribe “Nuestro universo”.','Este nombre no anticipa con claridad qué información voy a encontrar.','Una etiqueta ambigua.'),
('Vuelve a seleccionar esas palabras y escribe “Cómo funciona”.','Agrupar y nombrar contenidos es arquitectura de la información. Aquí el nombre ayuda a orientarse.','Una etiqueta descriptiva.'),
('Lee en voz alta los cinco bloques, de izquierda a derecha y de arriba abajo.','Cada sección debe responder una duda. El orden sirve a esa conversación.','La secuencia completa queda a la vista.')],
'Dile: “Ordena cinco secciones de tu página y explica por qué elegiste ese orden”.','Cierra cuando hayas mostrado un cambio de orden y uno de nombre.')
add('2.4','Editar diseño','Pulsa “2. Editar diseño” > “Reiniciar taller”.',[
('Haz clic dentro del título grande. Selecciona solo sus palabras y escribe “Asesoría para organizar tus consultas”.','En el boceto ya necesitamos palabras con significado, aunque todavía no terminemos el estilo.','Un título concreto.'),
('Haz clic en el párrafo de abajo y escribe “Revisamos cómo recibes consultas en una conversación inicial de 30 minutos”.','Esta frase explica el alcance. No prometemos resolver todo en una sola conversación.','Una descripción que concreta el servicio.'),
('Haz clic sobre el texto del botón verde del Taller y cámbialo por “Solicitar conversación”.','La llamada a la acción, o CTA, es el texto que invita a hacer algo y permite anticiparlo.','CTA específico dentro del boceto.'),
('En la tarjeta Oferta sustituye la pregunta por “Qué servicio ofrecemos y para quién”.','Cada bloque del esquema necesita una función. No basta con dibujar cajas vacías.','Primera tarjeta con contenido orientativo.'),
('En Contacto escribe “Nombre, correo y siguiente paso”.','Con este esquema ya puedo explicar cómo quiero que avance la persona antes de terminar el diseño.','El contenido del cierre de la página queda definido.')],
'Dile: “Crea un título, una descripción y un botón que expliquen tu servicio sin palabras genéricas”.','Cierra al tener tres textos y dos bloques con contenido. El botón del Taller es editable; no envía nada.')
add('3.1','Editar diseño','Pulsa “2. Editar diseño” > “Reiniciar taller”.',[
('Pulsa “Estilo confuso”. Señala la frase superior y el título.','Aquí hay elementos compitiendo. Lo más llamativo no coincide necesariamente con la información más importante.','Rótulo grande amarillo y título con menor prioridad.'),
('Pulsa “Estilo ordenado”.','Ahora el título tiene más presencia y la descripción acompaña. Esta organización es jerarquía visual.','Título dominante, texto de apoyo y acción.'),
('Alterna esos dos botones una vez, dejando un par de segundos entre cambios.','Compara qué miras primero. La jerarquía utiliza tamaño, contraste, espacio y posición.','El mismo contenido con dos prioridades visuales.'),
('Deja “Estilo ordenado” y cambia el título por “Soluciones para todos”.','Aunque la jerarquía esté ordenada, un texto impreciso sigue sin explicar bien el servicio.','Diseño ordenado con mensaje genérico.'),
('Restaura “Organiza la atención de tu negocio”.','Necesitamos claridad del contenido y claridad visual trabajando juntas.','Título concreto restaurado.')],
'Dile: “Señala qué debería verse primero, segundo y tercero en tu cabecera”.','Cierra después de comparar estilos y explicar por qué el contenido también importa.')
add('3.2','Editar diseño y página web','Pulsa “2. Editar diseño” > “Reiniciar taller”.',[
('Mueve “Tamaño del cuerpo” hasta 12. Lee una parte del párrafo.','Reducir demasiado el texto puede dificultar leer. Vamos a comprobarlo con el contenido real.','El párrafo se ve pequeño.'),
('Lleva el control a 18.','Este tamaño es nuestro punto de partida para el ejemplo, no una regla universal. Debemos revisar lectura y espacio.','El párrafo aumenta sin cambiar su contenido.'),
('Haz clic al final del párrafo y añade “Después coordinaremos contigo el siguiente paso según lo que necesites”.','Los textos reales pueden ser más largos. Hay que comprobar que la composición los admite.','El párrafo ocupa más líneas.'),
('Pulsa “1. Página web” > “Versión mejorada” > “Móvil 390”.','El ancho cambia y las líneas se reorganizan. Aquí compruebo que el título y la descripción siguen completos.','Página en una columna estrecha.'),
('Baja hasta las preguntas frecuentes y señala título y respuesta.','La tipografía también distingue niveles: un encabezado anuncia el tema y el párrafo lo explica.','Niveles de texto reconocibles.')],
'Dile: “Prueba un texto corto y otro largo. Revisa que ambos puedan leerse completos”.','Cierra cuando hayas mostrado tamaño, longitud y adaptación al ancho.')
add('3.3','Editar diseño','Pulsa “2. Editar diseño” y baja hasta “Contraste de texto sobre colores sólidos”.',[
('En Texto escribe #777777; en Fondo, #FFFFFF. Pulsa “Calcular”.','La razón ronda 4,48 a uno. Para texto normal, el mínimo AA es 4,5. Esta combinación queda por debajo.','4.48:1 y “Texto normal AA: no cumple”.'),
('Cambia Texto por #173D36 y pulsa “Calcular”.','Ahora el contraste es mayor. La selección del color debe considerar dónde se usa, además de la identidad visual.','11.95:1 y “cumple”.'),
('Señala el texto de muestra debajo del resultado.','Estamos midiendo texto sobre un fondo sólido. Esto no verifica una fotografía ni toda la accesibilidad de la web.','Muestra verde oscura sobre blanco.'),
('Pulsa “1. Página web” > “Versión mejorada”. Baja al formulario y envíalo vacío.','Un error no debe explicarse solo con rojo. El texto indica qué dato falta y qué hacer.','Borde de error y mensaje junto al campo.'),
('Lee el aviso de correo completo.','Usamos color y palabras. La persona no tiene que adivinar qué significa el estado.','Explicación comprensible del problema.')],
'Dile: “Comprueba dos colores y escribe un error que se entienda aunque no distingas el rojo”.','Cierra con dos resultados de contraste y un error explicado. Los umbrales y sus excepciones se amplían en las referencias.')
add('3.4','Editar diseño y página web','Pulsa “2. Editar diseño” > “Reiniciar taller”.',[
('Mueve “Separación” a 4 y señala los bordes entre tarjetas.','Cuando el espacio es muy pequeño, cuesta distinguir los grupos.','Tarjetas próximas.'),
('Mueve “Separación” a 24.','El espacio ayuda a reconocer qué pertenece a cada grupo. Elegimos una pauta y la aplicamos con coherencia.','Separación clara entre tarjetas.'),
('Señala títulos y párrafos dentro de dos tarjetas.','Al repetir una estructura, enseñamos al visitante cómo leer la siguiente. Esto es parte de trabajar con componentes.','Dos tarjetas con estructura equivalente.'),
('Pulsa “1. Página web” > “Versión mejorada”. Compara los dos botones de la cabecera.','El principal destaca la solicitud. El secundario permite conocer el proceso. Consistencia no significa que todos tengan igual importancia.','Botón sólido y botón con borde.'),
('Pulsa “Solicitar asesoría”. Haz clic en un campo y después envía vacío.','Un campo tiene distintos estados: disponible, con foco y con error. Diseñar también incluye esos cambios.','El mismo componente cambia de estado.')],
'Dile: “Define cómo se verá tu botón principal y un campo cuando tenga un error”.','Cierra tras enseñar espacio, repetición y estados.')
add('4.1','Página web','Pulsa “1. Página web” > “Versión mejorada” > “Escritorio”.',[
('Pulsa “Solicitar asesoría” dentro de la web. Escribe Ana y ana@example.com. Envía.','La primera heurística es saber qué ocurre: primero veo que está enviando y luego conozco el resultado.','Espera simulada y confirmación.'),
('Pulsa “Nueva demostración”. Después pulsa “Volver al servicio”. Señala el título.','La segunda trata de usar palabras que la persona comprenda. Aquí explicamos el servicio con lenguaje cotidiano.','Título concreto al inicio de la página.'),
('Vuelve al formulario, escribe Ana y pulsa “Volver al servicio”. Regresa al formulario.','La tercera trata del control: volver a leer no debería obligarme a perder lo que ya escribí.','El nombre Ana continúa en el campo.'),
('Pulsa “Borrar borrador”.','Esta acción sí borra. Por eso tiene un nombre que lo indica. Volver y borrar no significan lo mismo.','El nombre desaparece.'),
('Señala el formulario y resume los tres ejemplos.','Las heurísticas de Jakob Nielsen son criterios para revisar: información sobre el estado, lenguaje comprensible y control del recorrido.','Página lista para repetir la demostración.')],
'Dile: “Encuentra en una web un ejemplo de estado, lenguaje claro o control del usuario”.','Cierra tras demostrar los tres criterios con acciones distintas.')
add('4.2','Página web','Pulsa “1. Página web” > “Versión mejorada”.',[
('Señala “Solicitar asesoría” en el menú y en la cabecera. Pulsa uno.','Consistencia: la misma acción conserva un nombre que puedo reconocer en distintos lugares.','Ambos accesos llevan a la solicitud.'),
('Sin escribir nada, señala “obligatorio” y la explicación del correo.','Prevención de errores: antes de completar, ya sé qué necesito y para qué.','Requisitos visibles antes del intento.'),
('Señala “Conversación de 30 minutos” junto al formulario.','Reconocimiento antes que recuerdo: la información necesaria sigue a la vista; no me obligan a memorizarla.','Resumen del servicio en el momento de solicitar.'),
('Pulsa “Volver al servicio”. Recorre “Conocer el proceso” y luego vuelve al inicio.','Una persona nueva puede leer cómo funciona antes de decidir.','Ruta que incluye condiciones y proceso.'),
('Desde arriba pulsa directamente “Solicitar asesoría”.','Flexibilidad y eficiencia: quien ya conoce el servicio puede ir al contacto. Un camino directo no debe ocultar condiciones importantes.','Ruta corta al mismo formulario.')],
'Dile: “Identifica una regla consistente y una información que debería permanecer visible al contactar”.','Cierra después de mostrar las cuatro heurísticas, una por acción.')
add('4.3','Página web','Pulsa “1. Página web” > “Versión inicial”.',[
('Señala los anuncios amarillos y lee ambos.','Minimalismo significa dar prioridad a lo que ayuda. Estos mensajes repiten entusiasmo, pero no aclaran la oferta.','Dos mensajes promocionales genéricos.'),
('Pulsa “Versión mejorada” y busca “Así funciona”.','Hemos quitado ruido y conservado información necesaria. Una página útil no siempre es la más corta.','Duración, proceso y condiciones.'),
('Baja al formulario. Escribe Ana y, en el correo, solo ana. Pulsa “Solicitar asesoría”.','Recuperación de errores: el aviso me explica qué corregir y conserva el dato que estaba bien.','Error junto al correo y nombre conservado.'),
('Cambia ana por ana@example.com sin enviar todavía. Lee la ayuda debajo del correo.','Ayuda: la explicación aparece justo donde puede surgir la duda.','Campo corregido y propósito del dato visible.'),
('Sube hasta “Antes de solicitar”. Lee la respuesta a “¿Ya queda reservada una hora?”.','Esta ayuda aclara una condición importante antes de tomar la decisión.','Se explica que se coordina después, no que la cita ya esté reservada.')],
'Dile: “Reescribe un mensaje de error para que indique qué pasó y cómo continuar”.','Cierra después de enseñar contenido relevante, recuperación y ayuda.')
add('4.4','Página web y escribir un ejemplo','Pulsa “1. Página web” > “Versión inicial”; ve al formulario.',[
('Escribe Ana y ana. Pulsa “Enviar”.','Voy a documentar este problema de forma que otra persona pueda localizarlo y corregirlo.','Mensaje “Error 01”.'),
('Pulsa “3. Escribir un ejemplo” y elige “4.4”. Completa “Dónde” con “Formulario, al enviar correo inválido”.','Primero indico dónde aparece y qué estaba intentando hacer.','Ubicación y acción en el documento.'),
('Completa “Problema” con “Error 01 no indica qué corregir”; en “Criterio”, escribe “Recuperación de errores”.','El criterio ayuda a explicar el problema. No reemplaza la descripción concreta.','Problema específico y heurística relacionada.'),
('En “Impacto estimado” escribe “3: podría bloquear la solicitud”.','Usamos una escala sencilla propia del curso: uno menor, dos relevante y tres bloqueo. Aquí es una estimación, no un resultado medido.','Impacto identificado como estimado.'),
('Completa “Cambio” con “Explicar el error junto al correo”; “Comprobar” con “Observar si la persona lo corrige sin ayuda”.','Ahora el hallazgo termina en una acción y una forma de comprobarla.','Ficha completa y utilizable.')],
'Dile: “Documenta un problema con ubicación, explicación y propuesta de mejora”.','Cierra cuando la ficha permita entender el problema sin volver a ver la grabación.',
'Dónde:\nAcción intentada: enviar una solicitud.\nProblema:\nCriterio:\nImpacto estimado:\nCambio:\nComprobar:\n')
add('5.1','Editar diseño y página web','Pulsa “2. Editar diseño” > “Reiniciar taller”.',[
('Cambia el título del Taller por “Impulsa tu potencial”.','Esta frase no permite reconocer con claridad el servicio. Vamos a corregirla con una decisión de contenido.','Título genérico en el boceto.'),
('Sustitúyelo por “Organiza la atención de tu negocio”.','Ahora la persona puede relacionar la oferta con un problema que conoce.','Oferta explícita.'),
('En la descripción escribe “Revisamos cómo recibes consultas en una conversación inicial de 30 minutos”.','El apoyo explica el alcance; el título no necesita cargar con toda la información.','Alcance debajo del título.'),
('Cambia el texto verde por “Solicitar asesoría”.','El botón describe el siguiente paso. No promete una cita que todavía no se ha coordinado.','Acción coherente con el proceso.'),
('Pulsa “1. Página web” > “Versión mejorada” > “Conocer el proceso”.','Ahora compruebo que el enlace lleva a la información que anuncia. Una etiqueta clara también necesita un destino correcto.','Sección “Así funciona”.')],
'Dile: “Escribe una cabecera que responda qué ofreces, a quién ayuda y cómo continuar”.','Cierra con título, descripción y acción ya escritos, y un destino comprobado.')
