source=(old/'index.html').read_text()
css=re.search(r'<style>(.*?)</style>',source,re.S).group(1)
case=re.search(r'<section id="case".*?</section>',source,re.S).group(0).replace(' hidden','',1).replace('Caso inicial','Versión inicial').replace('Caso mejorado','Versión mejorada').replace('caso-mejorado.html','recursos/caso-mejorado.html').replace('>Abrir caso en otra pestaña<','>Abrir solo la web<')
