board='''<section id="sheets" class="panel" hidden><div class="toolbar"><label for="example">Ejemplo de la clase</label><select id="example"></select><button id="loadExample">Cargar de nuevo este ejemplo</button><button id="downloadSheet">Guardar lo que escribí</button></div><p>Haz clic después de cada etiqueta y escribe. Los cambios permanecen al cambiar de pestaña, pero no al cerrar. Descarga tu trabajo para conservarlo.</p><textarea id="sheet" aria-label="Documento para escribir"></textarea></section>'''
js=r'''
const lessons=DATA,el=id=>document.getElementById(id);let currentExample='';
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.panel').forEach(x=>x.hidden=x.id!==b.dataset.tab);document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));});
function setCase(path){el('frame').src='recursos/'+path;el('caseLink').href='recursos/'+path;el('initial').classList.toggle('active',path.includes('inicial'));el('improved').classList.toggle('active',path.includes('mejorado'));}
el('initial').onclick=()=>setCase('caso-inicial.html');el('improved').onclick=()=>setCase('caso-mejorado.html');el('restart').onclick=()=>{el('frame').src=el('frame').getAttribute('src')};
el('desktop').onclick=()=>{el('case').classList.remove('mobile');el('desktop').classList.add('active');el('mobile').classList.remove('active')};el('mobile').onclick=()=>{el('case').classList.add('mobile');el('mobile').classList.add('active');el('desktop').classList.remove('active')};
const names=['Oferta','Beneficios','Cómo funciona','Preguntas frecuentes','Contacto'];function fill(){el('blocks').innerHTML='';for(const title of names){const d=document.createElement('article');d.className='card';const h=document.createElement('h3');h.contentEditable='true';h.textContent=title;const p=document.createElement('p');p.contentEditable='true';p.textContent='¿Qué pregunta del visitante responde esta sección?';d.append(h,p);for(const [label,dir]of [['Subir',-1],['Bajar',1]]){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{if(dir===-1&&d.previousElementSibling)d.parentNode.insertBefore(d,d.previousElementSibling);if(dir===1&&d.nextElementSibling)d.parentNode.insertBefore(d.nextElementSibling,d)};d.append(b);}el('blocks').append(d);}}
fill();const reset=el('practice').innerHTML;el('confused').onclick=()=>el('practice').classList.add('confused');el('ordered').onclick=()=>el('practice').classList.remove('confused');el('fontSize').oninput=()=>{el('practice').style.setProperty('--body',el('fontSize').value+'px');el('fontVal').textContent=el('fontSize').value};el('spacing').oninput=()=>{el('practice').style.setProperty('--space',el('spacing').value+'px');el('spaceVal').textContent=el('spacing').value};el('resetWorkshop').onclick=()=>{el('practice').innerHTML=reset;el('practice').removeAttribute('style');el('practice').classList.remove('confused');el('fontSize').value=18;el('spacing').value=24;el('fontVal').textContent='18';el('spaceVal').textContent='24';fill();};
function lum(h){const [r,g,b]=h.slice(1).match(/../g).map(x=>parseInt(x,16)/255).map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4);return r*.2126+g*.7152+b*.0722;}
el('calc').onclick=()=>{let a=el('fg').value.trim(),b=el('bg').value.trim();if(!/^#[\da-f]{6}$/i.test(a)||!/^#[\da-f]{6}$/i.test(b)){el('ratio').textContent='Escribe un color de seis cifras, por ejemplo #777777.';return;}const x=lum(a),y=lum(b),r=(Math.max(x,y)+.05)/(Math.min(x,y)+.05);el('ratio').textContent=r.toFixed(2)+':1 · Texto normal AA: '+(r>=4.5?'cumple':'no cumple')+' · Texto grande AA: '+(r>=3?'cumple':'no cumple');el('contrastSample').style.color=a;el('contrastSample').style.background=b;};el('calc').click();
for(const l of lessons.filter(x=>x.board)){const o=document.createElement('option');o.value=l.id;o.textContent=l.id+' · '+l.title;el('example').append(o);}
function load(){const x=lessons.find(x=>x.id===el('example').value);el('sheet').value=x.board;currentExample=x.id;}
el('example').onchange=()=>{if(el('sheet').value.trim()&&currentExample&&el('sheet').value!==lessons.find(x=>x.id===currentExample).board){if(!confirm('Cambiar de ejemplo reemplazará lo escrito. ¿Ya guardaste lo que quieres conservar?')){el('example').value=currentExample;return;}}load()};el('loadExample').onclick=()=>{if(confirm('¿Borrar los cambios y volver al ejemplo inicial?'))load()};load();
el('downloadSheet').onclick=()=>{const url=URL.createObjectURL(new Blob([el('sheet').value],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='ejemplo-'+currentExample+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
'''
# Raw JavaScript regex needs one backslash, unlike Python regular strings.
js=js.replace('[\\da-f]','[\\da-f]')
app='<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pantalla para grabar | Curso UX/UI</title><style>'+css+'header button{font-weight:bold}iframe{height:760px}.toolbar a{color:#173d36}.card button{margin-right:5px}output{font-weight:bold}header strong{font-size:16px}@media(max-width:800px){header button{font-size:15px}}</style><body><header><strong>PANTALLA PARA GRABAR</strong><button data-tab="case" class="active">1. Página web</button><button data-tab="workshop">2. Editar diseño</button><button data-tab="sheets">3. Escribir un ejemplo</button></header><main>'+case+work+board+'</main><script>'+js.replace('DATA',json.dumps(D,ensure_ascii=False).replace('</','<\\/'))+'</script></body></html>'
(O/'PANTALLA-PARA-GRABAR.html').write_text(app)
# Guía: una página de instrucciones por clase. No necesita leer código ni instalar herramientas.
styles='''@page{size:A4;margin:0}*{box-sizing:border-box}html{background:#e9eeea}body{margin:0;color:#1c352c;font:10.7pt/1.42 Arial,Helvetica,sans-serif;-webkit-print-color-adjust:exact;print-color-adjust:exact}.page{background:#fffefa;width:210mm;height:297mm;padding:14mm 16mm 18mm;margin:7mm auto;position:relative;break-after:page}.page:last-child{break-after:auto}.top{display:flex;justify-content:space-between;font-size:7.7pt;letter-spacing:1px;text-transform:uppercase;border-bottom:1px solid #c5d4c6;padding-bottom:3mm;margin-bottom:5mm;color:#25664c}.foot{position:absolute;bottom:9mm;left:16mm;right:16mm;display:flex;justify-content:space-between;border-top:1px solid #c5d4c6;padding-top:3mm;font-size:7.6pt;color:#5c7363}.eyebrow{font-size:8pt;text-transform:uppercase;letter-spacing:1px;color:#247453;font-weight:bold;margin:0 0 2mm}h1{font-size:30pt;line-height:1.07;letter-spacing:-1px;margin:0 0 5mm}h2{font-size:21pt;line-height:1.15;margin:0 0 4mm}h3{font-size:12pt;margin:4mm 0 2mm}p{margin:0 0 3mm}.lead{font-size:13pt;color:#496852}.box{background:#eaf3e9;border-left:3px solid #247453;padding:4mm;margin:4mm 0}.dark{background:#173d36;color:white;padding:5mm;border-radius:3mm;margin:5mm 0}.dark p:last-child,.box p:last-child{margin:0}ol,ul{padding-left:5mm}li{margin-bottom:3mm}.small{font-size:9.5pt}.tiny{font-size:8pt}.muted{color:#5c7363}.shot{width:100%;border:1px solid #c7d8c7;border-radius:2mm;margin:3mm 0}.step{display:grid;grid-template-columns:8mm 1fr;gap:3mm;padding:3mm 0;border-bottom:1px solid #d6e1d2}.number{font-size:14pt;font-weight:bold;color:#18704c}.step p{margin:0 0 1.3mm;font-size:10pt;line-height:1.38}.step p:last-child{margin:0}.step .say{color:#244b38}.step .result{font-size:9pt;color:#5d7160}.prep{font-size:9.4pt;padding:3mm;background:#eaf3e9;margin-bottom:2mm}.end{font-size:9pt;margin-top:3mm}.lesson h2{font-size:19pt}.lesson .box{font-size:9.5pt;margin:3mm 0;padding:3mm}a{color:#176548;text-underline-offset:2px}.jump{position:sticky;top:0;background:#173d36;color:white;padding:13px 18px;display:flex;gap:10px;align-items:center;flex-wrap:wrap;z-index:20}.jump button,.jump select,.jump a{font:16px Arial;padding:9px;border:1px solid #b7cdb9;border-radius:5px;color:#173d36;background:white;text-decoration:none}.grid{display:grid;grid-template-columns:1fr 1fr;gap:4mm}.card{border:1px solid #c7d8c7;border-radius:2mm;padding:4mm}.refs{font-size:9pt}.refs li{margin-bottom:2mm}@media print{html{background:white}.page{margin:0}.jump{display:none}}@media screen and (max-width:820px){.page{width:100%;height:auto;margin:0 0 16px;padding:24px}.foot{position:static;margin-top:25px}.grid{grid-template-columns:1fr}.jump select{max-width:100%}}
'''
pages=[]
def page(kicker,title,body,cls='',id=''):
 i=len(pages)+1
 pages.append(f'<section class="page {cls}" id="{id or "p"+str(i)}"><div class="top"><span>Guía práctica del profesor</span><span>UX/UI · Paso a paso</span></div><main><p class="eyebrow">{kicker}</p><h2>{title}</h2>{body}</main><footer class="foot"><span>Abre · Haz · Di · Comprueba</span><span>{i:02d} / 28</span></footer></section>')
page('Empieza aquí','Una ruta concreta para enseñar.','''
<h1>Qué abrir, qué pulsar<br>y qué explicar.</h1><p class="lead">Esta guía acompaña las 24 clases. En cada una tienes una secuencia de cinco acciones que puedes ensayar y grabar.</p>
<div class="dark"><p><strong>Herramienta elegida: el navegador.</strong> Mostrarás la página y el editor de práctica que vienen en esta carpeta. Figma no es necesario para este recorrido. Los diseños y los estados del formulario ya están preparados para enseñar los conceptos.</p></div>
<h3>Solo tienes que abrir dos cosas</h3><ol><li><strong>EMPEZAR-AQUI.html:</strong> esta guía. Es para ti; aquí lees qué hacer y qué decir.</li><li><strong>PANTALLA-PARA-GRABAR.html:</strong> la ventana que verá el alumno. Ábrela con el botón de arriba o con doble clic en el archivo.</li></ol>
<p>Conserva la carpeta <strong>recursos</strong> junto a esos archivos. No tienes que abrirla ni modificar código. Todo funciona localmente. El caso es ficticio y el formulario no envía información real.</p>
<h3>Cómo leer cada clase</h3><ul><li><strong>Abre antes de grabar:</strong> deja lista la pantalla indicada.</li><li><strong>Haz:</strong> movimiento del ratón, clic o texto exacto que debes escribir.</li><li><strong>Di:</strong> una explicación que puedes usar mientras haces la acción.</li><li><strong>Debes ver:</strong> el resultado que confirma que seguiste bien el paso.</li><li><strong>Ejercicio que le pides hacer:</strong> frase para que el alumno pause y practique.</li></ul>
<div class="box"><strong>“Consigna” significaba ejercicio o instrucción para el alumno.</strong> Por ejemplo: “Pausa el video y escribe un título que explique tu servicio”. En esta versión usaré esa forma directa.</div>
<p class="small muted">Primero completa la demostración con calma. Las duraciones del temario siguen como referencia; no intentes llenar minutos repitiendo frases. La toma piloto servirá para ajustar la explicación y la práctica a las cuatro horas previstas.</p>
''')
page('Conoce tu pantalla','Tres botones. Cada uno tiene una función.','''
<img class="shot" src="recursos/mapa-pantalla.png" alt="Pantalla de práctica con los tres botones principales y la comparación de versiones">
<h3>1. Página web</h3><p>Sirve para <strong>mostrar y usar</strong> el ejemplo. “Versión inicial” enseña problemas. “Versión mejorada” enseña una posible solución. “Móvil 390” cambia el ancho. Puedes bajar, pulsar enlaces, escribir y enviar el formulario simulado.</p>
<h3>2. Editar diseño</h3><p>Sirve para <strong>cambiar algo mientras explicas</strong>: título, párrafo, texto del botón y orden de las tarjetas. Haz clic dentro de las palabras; selecciónalas arrastrando el ratón y escribe el reemplazo. Los botones Subir/Bajar mueven tarjetas. Los controles de tamaño y separación muestran su valor.</p>
<h3>3. Escribir un ejemplo</h3><p>Sirve como <strong>hoja visible de trabajo</strong>. Selecciona el número de la clase y escribe después de las etiquetas. La guía te dice exactamente qué poner. No es necesario crear tablas ni abrir un documento aparte.</p>
<div class="box small"><strong>Dos botones que no debes confundir:</strong> el texto verde de “Editar diseño” es editable y no envía nada. El botón “Solicitar asesoría” de “Página web” sí activa la simulación del formulario.</div>
<p class="small">Reiniciar el Taller elimina sus cambios. Cambiar de ejemplo escrito reemplaza lo que escribiste, previa confirmación cuando hay cambios. Usa “Guardar lo que escribí” antes de cerrar si quieres conservarlo.</p>
''')
page('Antes del primer video','Cómo preparar y grabar en tu Mac.','''
<h3>Haz una prueba de 30 segundos</h3><ol><li>Abre esta guía y la pantalla de práctica en ventanas separadas. Coloca la guía fuera del área que vas a grabar: en otra pantalla, impresa o en otra parte del escritorio.</li><li>Deja lista la página de práctica en el paso de la clase. Ajusta su tamaño para leer bien los textos.</li><li>Pulsa <strong>Mayúsculas + Comando + 5</strong>. Elige la opción para grabar una parte seleccionada de la pantalla y marca solo la ventana de práctica.</li><li>En <strong>Opciones</strong>, selecciona el micrófono que usarás. Pulsa <strong>Grabar</strong>, di dos frases y haz un clic de prueba.</li><li>Detén la grabación con el botón de detener de la barra de menús. Reproduce el archivo y comprueba que se escucha tu voz y se lee la pantalla.</li></ol>
<p class="tiny muted">Referencia de los controles de captura: <a href="https://support.apple.com/es-es/102618">Apple · Cómo grabar la pantalla del Mac</a>. La apariencia puede variar con la versión del sistema.</p>
<h3>Ahora graba una clase</h3><ol><li>Ensaya sus cinco pasos una vez sin grabar. Si no ves el resultado descrito, revisa el archivo y el botón antes de continuar.</li><li>Empieza la toma en la pantalla indicada. Di qué van a aprender con una frase sencilla.</li><li>Haz el paso 1, explica lo que ocurrió y continúa. No necesitas hablar mientras buscas dónde está un botón: ya lo ensayaste.</li><li>Al finalizar, lee el ejercicio y pide al alumno pausar el video. No grabes varios minutos de silencio para que lo resuelva.</li><li>Detén, revisa y nombra el archivo con módulo y clase, por ejemplo <strong>M01-L01-toma01.mov</strong>.</li></ol>
<div class="dark"><p><strong>Si solo tienes una pantalla:</strong> puedes grabar por fragmentos. Revisa el siguiente paso fuera de la toma y vuelve a grabar la demostración. Después unes los fragmentos. Tu cámara no es necesaria para empezar.</p></div>
<p class="small">“Di” es una base para explicar con tus palabras, no una obligación de memorizar. Si un concepto no te resulta claro, ensáyalo con el ejemplo antes de grabarlo. La guía indica la pantalla exacta para evitar que tengas que improvisarla.</p>
''')
for x in D:
 b=f'<p class="small"><strong>Mostrarás:</strong> {e(x["where"])} · Referencia del temario: {x["minutes"]} min.</p><div class="prep"><strong>Abre antes de grabar:</strong> {e(x["prep"])}</div>'
 for j,s in enumerate(x['steps'],1):
  b+=f'<article class="step"><div class="number">{j:02d}</div><div><p><strong>Haz:</strong> {e(s["action"])}</p><p class="say"><strong>Di:</strong> “{e(s["say"])}”</p><p class="result"><strong>Debes ver:</strong> {e(s["see"])}</p></div></article>'
 b+=f'<div class="box"><strong>Ejercicio que le pides hacer:</strong> {e(x["task"])}</div><p class="end"><strong>Cuándo terminar:</strong> {e(x["end"])}</p>'
 page('Clase '+x['id'],x['title'],b,'lesson','clase-'+x['id'].replace('.','-'))
page('Si algo no sale como esperabas','Resuelve estas dudas antes de grabar.','''
<h3>“¿Tengo que diseñar algo en Figma?”</h3><p>En esta versión, no. Harás los cambios del ejemplo en <strong>Editar diseño</strong> y mostrarás su aplicación en <strong>Página web</strong>. El objetivo es enseñar decisiones de UX/UI. No se enseña a construir el archivo técnico de una web ni a manejar Figma.</p>
<h3>“Cambié el título del Taller, pero no cambió la página”</h3><p>Son dos materiales diferentes. El Taller es un boceto para modificar en directo; la página es una demostración preparada. Al cambiar de uno a otro di: “Ya vimos la decisión en el boceto; ahora veamos cómo se aplica en una página”.</p>
<h3>“El botón verde no funciona”</h3><p>En <strong>Editar diseño</strong> es un texto editable. Para mostrar el envío, entra en <strong>Página web</strong>, elige <strong>Versión mejorada</strong> y baja al formulario.</p>
<h3>“No tengo una persona para la clase 6.2”</h3><p>Puedes ensayar representando la situación y diciendo que es una simulación. Para grabar una prueba real necesitas una persona que no reciba la ruta por adelantado. No inventes sus respuestas.</p>
<h3>“No sé qué decir después de pulsar”</h3><p>Lee la frase <strong>Di</strong> de ese paso. Señala el resultado y relaciona lo que acaba de pasar con la dificultad del visitante. Evita repetir únicamente el nombre del botón.</p>
<h3>“Mi grabación duró menos de lo previsto”</h3><p>Revisa si explicaste la razón del cambio, mostraste el antes y el después y resolviste un ejemplo. No añadas silencios para alcanzar un tiempo. Usa el piloto para ajustar la duración final del curso con Daxus.</p>
<p class="small section"><strong>Lecturas de apoyo:</strong> <a href="https://www.nngroup.com/articles/ten-usability-heuristics/">Las diez heurísticas de Jakob Nielsen</a> · <a href="https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html">W3C: contraste mínimo</a> · <a href="https://www.nngroup.com/articles/usability-testing-101/">Pruebas de usabilidad</a>. El caso Faro y sus condiciones son ficticios.</p>
''')
